-- Relink active NCLEX forms 1-43 to 85 unique active+qaPassed items each.
-- No item is shared across these forms.
-- Blueprint counts sit inside the NCSBN 85-item ranges and fit the eligible pool:
--   management-of-care 17, safety-infection 11, health-promotion 7,
--   psychosocial 8, basic-care-comfort 7, pharmacology-nursing 14,
--   reduction-risk 9, physiological-adaptation 12.
-- The historical 15/11/8/8/8/13/10/12 mix cannot be met without overlap:
-- reduction-risk, basic-care, and health-promotion do not have 43 times those counts.
-- Backup table: nclex_exam_question_backup_20261128. Undo: 03-undo.sql.
-- Dry-run: 02-dryrun.sql (same writes, then ROLLBACK). Not applied by deploy.
BEGIN;
CREATE TABLE IF NOT EXISTS nclex_exam_question_backup_20261128 AS
SELECT l.*
FROM nclex_full_practice_exam_questions l
JOIN nclex_full_practice_exams e ON e.id = l."examId"
WHERE e.active AND e."questionCount" = 85
  AND e."examNumber" BETWEEN 1 AND 43;

